                <?php elseif ($tab === 'security' && !$isSelf): ?><article class="card"><div class="card-title"><div><h2>Segurança da conta</h2><p>Status dos fatores de autenticação configurados pelo próprio usuário.</p></div><span class="status <?= !empty($totpEnabled) ? 'enabled' : 'disabled' ?>"><i></i><?= !empty($totpEnabled) ? '2FA ativa' : '2FA desativada' ?></span></div><div class="permission-row"><strong>Último acesso registrado</strong><span><?= $e($lastLogin ?? '—') ?></span></div></article>
                <?php elseif ($tab === 'security'): ?>
                    <article class="card security-card"><div class="card-title"><div><h2>Autenticação em duas etapas</h2><p>Use um aplicativo autenticador compatível com TOTP.</p></div><span class="status <?= !empty($totpEnabled) ? 'enabled' : 'disabled' ?>"><i></i><?= !empty($totpEnabled) ? 'Ativa' : 'Desativada' ?></span></div>
                    <?php if (!empty($recoveryCodes)): ?><div class="recovery-box"><h3>Guarde seus códigos de recuperação</h3><p>Esta tela é a única exibição; armazene-os fora deste dispositivo.</p><div class="recovery-codes"><?php foreach ($recoveryCodes as $code): ?><code><?= $e($code) ?></code><?php endforeach; ?></div></div><?php endif; ?>
                    <?php if (!empty($pendingUri)): ?><div class="totp-setup"><div><h3>Conecte seu autenticador</h3><p>Escaneie o QR local ou cadastre a chave manualmente. O segredo não é enviado a terceiros.</p><?php if (!empty($qr)): ?><img class="totp-qr" src="<?= $e($qr) ?>" alt="QR Code de configuração TOTP"><?php endif; ?><details><summary>Não consegue escanear?</summary><code class="manual-key"><?= $e($manualSecret ?? '') ?></code></details></div><form method="post" action="<?= $e(url('profile/two-factor/confirm')) ?>"><input type="hidden" name="_token" value="<?= $e($csrf) ?>"><label>Código do aplicativo<input name="code" inputmode="numeric" maxlength="6" required></label><button class="button primary" type="submit">Confirmar e ativar</button></form></div><?php elseif (empty($totpEnabled)): ?><form class="inline-form" method="post" action="<?= $e(url('profile/two-factor/setup')) ?>"><input type="hidden" name="_token" value="<?= $e($csrf) ?>"><label>Confirme sua senha<input type="password" name="current_password" autocomplete="current-password" required></label><button class="button primary" type="submit">Ativar 2FA</button></form><?php else: ?><form class="inline-form" method="post" action="<?= $e(url('profile/two-factor/disable')) ?>"><input type="hidden" name="_token" value="<?= $e($csrf) ?>"><label>Senha atual<input type="password" name="current_password" autocomplete="current-password" required></label><label>Código TOTP ou recuperação<input name="code" maxlength="64" required></label><button class="button danger" type="submit">Desativar 2FA</button></form><?php endif; ?></article>
                    <form class="card form-card" method="post" action="<?= $e(url('profile/password')) ?>"><input type="hidden" name="_token" value="<?= $e($csrf) ?>"><div class="card-title"><div><h2>Alterar senha</h2><p>Outras sessões serão encerradas após a alteração.</p></div></div><div class="form-grid"><label>Senha atual<input type="password" name="current_password" autocomplete="current-password" required></label><label>Nova senha<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required></label></div><div class="form-actions"><button class="button primary" type="submit">Atualizar senha</button></div></form>
                <?php elseif ($tab === 'sessions'): ?>
                    <article class="card table-card"><div class="card-title"><div><h2>Sessões e dispositivos</h2><p>Identificação aproximada pelo navegador, sem localização.</p></div><?php if ($isSelf): ?><form method="post" action="<?= $e(url('profile/sessions/revoke-others')) ?>"><input type="hidden" name="_token" value="<?= $e($csrf) ?>"><button class="button secondary" type="submit">Encerrar outras sessões</button></form><?php endif; ?></div><div class="table-wrap"><table><thead><tr><th>Dispositivo</th><th>Iniciada</th><th>Última atividade</th><th>Status</th></tr></thead><tbody><?php foreach (($sessions ?? []) as $session): ?><tr><td><?= $e($session['device_label']) ?> <?= isset($currentHash) && hash_equals((string) $currentHash, (string) $session['session_hash']) ? '· Esta sessão' : '' ?></td><td><?= $e($session['created_at']) ?></td><td><?= $e($session['last_activity_at']) ?></td><td><?= $session['revoked_at'] === null ? 'Ativa' : 'Encerrada' ?></td></tr><?php endforeach; ?></tbody></table></div></article>
                <?php elseif ($tab === 'activity'): ?><article class="card table-card"><div class="card-title"><div><h2>Logs de atividade</h2><p>Eventos de segurança, sem senhas, tokens ou segredos.</p></div></div><div class="table-wrap"><table><thead><tr><th>Evento</th><th>Data</th></tr></thead><tbody><?php foreach (($events ?? []) as $event): ?><tr><td><?= $e(str_replace('_', ' ', $event['event_type'])) ?></td><td><?= $e($event['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></article>
                <?php endif; ?>
            <?php endif; ?>
        </section>
    </main>
</div>
<?php if (in_array($view, ['editor-demo', 'page-form'], true)): ?><script src="<?= $e(url('cms-assets/wysiwyg/js/app.js?v=1.0.0')) ?>" defer></script><?php endif; ?>
<script src="<?= $e(url('assets/cms-default.min.js?v=20261008-code024')) ?>" defer></script>
